import{z as o,x as n,o as l,c as d,q as r,j as t,D as e,d as E,s as i,S as s,b as A}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"低资源语言","description":"","frontmatter":{"title":"低资源语言","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ml-low-resource.md","filePath":"llm/ml-low-resource.md","lastUpdated":1791063341000}'),m={name:"llm/ml-low-resource.md"};function h(p,a,D,F,u,f){const B=n("Mermaid");return l(),d("div",null,[a[2]||(a[2]=r('<h1 id="低资源语言" tabindex="-1">低资源语言 <a class="header-anchor" href="#低资源语言" aria-label="Permalink to &quot;低资源语言&quot;">​</a></h1><div class="epigraph"><p>全球约七千种活语言，绝大多数没有多少数字文本；「低资源」缺的不是语言学复杂度，而是爬虫与标注预算。</p><footer>—— 据 Joshi 等，ACL 2020；Team NLLB，2022；MasakhaNER 共建实践整理</footer></div><p><a href="/llm/ml-crosslingual-transfer">上一课</a>写明迁移不搬运知识：两边语料都没有的东西，任何对齐机制都变不出来。缺口随即而来：对上百种语言，语料就是没有。本课写低资源语言的数据获取、模型与配比，不重讲迁移机制。后课的多语言评测要给这些语言单列分数，默认你会先判断一门语言的资源档位。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>低资源不是二值标签。Joshi 等 2020 按说话人数量对数据量的比分层：数亿人使用却几乎无数字文本的语言，比几百万人的欧洲小语种更难——后者至少有议会记录与报纸存档。工程要回答三个问题：文本从哪来；模型怎么练；练完怎么知道没有自欺。</p><p>三条坏路都常见。一是硬凑：用英语语料的翻译冒充原生语料，模型学到的只是翻译腔的影子。二是过采样：把稀缺语料重复几十遍灌进配比，撞上<a href="/llm/data-constrained-scaling">数据约束下的扩展</a>给出的重复报酬递减。三是盲目上大词表：名额给足，但每个词条见次太少，尾部词条退化成 glitch。正确做法是按档位组合策略。</p><p><span class="marginnote">「见次」就是出现次数：一个词在训练语料里被模型看到的次数。数字实例：词表 5 万词条、语料只有 10 MB 时，排在尾部的词可能全文只出现三五次——模型对它的记忆相当于人只见过一个生词三遍，自然记不牢，这就是「名额给了也白给」的原因。</span></p><h3 id="数据侧-三条获取路径" tabindex="-1">数据侧：三条获取路径 <a class="header-anchor" href="#数据侧-三条获取路径" aria-label="Permalink to &quot;数据侧：三条获取路径&quot;">​</a></h3><p>原生爬取：该语言的网页文本本来就稀，而且语言识别会把短文本误判回高资源语言（见<a href="/llm/langid-safety-filter">语言识别与安全过滤</a>），需要更敏感的识别阈值加人工抽查。翻译合成：用机器翻译把高资源语料译入目标语言，规模可控、质量控制难，教给模型的是「目标语言的翻译体」。社区采集与标注：MasakhaNER 一类由非洲研究者社区共建的标注集质量最高、量最小，还自带方言与正字法多样性。三条路径按配比混合，配比本身是实验对象，进台账。</p><p><span class="marginnote">Ethnologue 记录约七千种活语言，常用 NLP 基准合计覆盖不足百种。Joshi 等 2020 把多数语言划进「几乎无数字文本」档位——覆盖的瓶颈在数据基础设施，不在模型结构。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>模型侧按档位降级。数据极小时，小模型小词表可能优于大模型大词表：AfriBERTa 用几 MB 级语料训练小型编码器，在非洲语言命名实体识别上可用（Ogueji 等 2021）——小词表让每个词条见次不至于太稀，这是<a href="/llm/ml-tokenizer-multilingual">多语言分词的工程</a>名额账在低资源端的反面。未见字符用<a href="/llm/byte-fallback">字节回退</a>兜底。机器翻译是低资源的最大单一受益者：NLLB-200 覆盖 202 种语言，靠的是「爬取、翻译合成、人类评估」的流水线（Team NLLB 2022）。配比上，低资源语言的重复次数、合成数据占比与回退路径都要写进实验台账，与<a href="/llm/data-mixture-laws">数据配比定律</a>的账本同一套记法。</p><p><span class="marginnote">「几 MB 级语料」是什么概念？一部中文长篇小说的纯文本大约 1 MB，几 MB 就相当于几部小说；而主流英语预训练语料以 TB 计，差着五六个数量级。AfriBERTa 说明的不是「数据少没关系」，而是任务不同、目标不同时，小数据也有可用的下限打法。</span></p>',13)),(l(),t(s,null,{default:e(()=>[i(B,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E7%9B%AE%E6%A0%87%E8%AF%AD%E8%A8%80%E6%95%B0%E6%8D%AE%E6%9C%89%E5%A4%9A%E5%B0%91%EF%BC%9F%22%7D%20--%3E%7C%22%E5%87%A0%E4%B9%8E%E4%B8%BA%E9%9B%B6%22%7C%20T1%5B%22%E5%B0%8F%E6%A8%A1%E5%9E%8B%20%2B%20%E5%B0%8F%E8%AF%8D%E8%A1%A8%20%2B%20%E5%AD%97%E8%8A%82%E5%9B%9E%E9%80%80%22%5D%0A%20%20Q%20--%3E%7C%22MB%20%E7%BA%A7%22%7C%20T2%5B%22%E5%B0%8F%E6%A8%A1%E5%9E%8B%E4%BC%98%E5%85%88%EF%BC%8C%E8%B0%A8%E6%85%8E%E9%87%8D%E5%A4%8D%E4%B8%8E%E5%90%88%E6%88%90%22%5D%0A%20%20Q%20--%3E%7C%22%E7%99%BE%20MB%20%E4%BB%A5%E4%B8%8A%22%7C%20T3%5B%22%E5%B8%B8%E8%A7%84%E5%A4%9A%E8%AF%AD%E8%A8%80%E8%AE%AD%E7%BB%83%EF%BC%8C%E7%9B%AF%E5%B0%BE%E9%83%A8%E8%AF%8D%E6%9D%A1%22%5D%0A%20%20T1%20--%3E%20MT%5B%22%E6%9C%BA%E5%99%A8%E7%BF%BB%E8%AF%91%E4%BD%9C%E4%B8%BA%E6%9D%A0%E6%9D%86%22%5D%0A%20%20T2%20--%3E%20MT%0A%20%20MT%20--%3E%20EVAL%5B%22%E5%88%86%E5%88%97%E8%AF%84%E6%B5%8B%E5%B9%B6%E6%8A%A5%E5%91%8A%E8%AF%91%E6%96%87%E5%8D%B7%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20T3%20--%3E%20EVAL%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[E("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,[E("低资源的中心机制是数据效率与表容量的张力。整子词需要见次学习，而语料不给见次，于是名额问题走向三个出口：缩（小词表）、绕（字节路径）、灌（用翻译合成把见次制造出来）。灌有副作用：合成数据把源语言的句法结构带进目标语言，模型生成的文本会带翻译腔，母语者一读便知；更危险的是自我强化——用合成数据训出的模型再产数据，腔调被放大。评测侧同理："),A("a",{href:"/llm/multilingual-benchmarks"},"多语言基准"),E("区分译文卷与原生卷，低资源语言往往只有译文卷可用，这本身就是要报告的缺口，不是可以忽略的空白。")],-1)),(l(),t(s,null,{default:e(()=>[i(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20LID%5B%22%E8%AF%AD%E8%A8%80%E8%AF%86%E5%88%AB%E4%B8%8E%E4%BA%BA%E5%B7%A5%E6%8A%BD%E6%9F%A5%22%5D%20--%3E%20CRAWL%5B%22%E5%8E%9F%E7%94%9F%E7%88%AC%E5%8F%96%EF%BC%9A%E7%A8%80%22%5D%0A%20%20SRC%5B%22%E9%AB%98%E8%B5%84%E6%BA%90%E6%BA%90%E8%AF%AD%E6%96%99%22%5D%20--%3E%20SYN%5B%22%E7%BF%BB%E8%AF%91%E5%90%88%E6%88%90%EF%BC%9A%E9%87%8F%22%5D%0A%20%20COMM%5B%22%E7%A4%BE%E5%8C%BA%E9%87%87%E9%9B%86%E6%A0%87%E6%B3%A8%EF%BC%9A%E8%B4%A8%22%5D%20--%3E%20MIX%5B%22%E9%85%8D%E6%AF%94%E6%B7%B7%E5%90%88%E4%B8%8E%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20CRAWL%20--%3E%20MIX%0A%20%20SYN%20--%3E%20MIX%0A%20%20MIX%20--%3E%20TRAIN%5B%22%E5%B0%8F%E8%AF%8D%E8%A1%A8%E6%88%96%E5%AD%97%E8%8A%82%E8%B7%AF%E5%BE%84%E8%AE%AD%E7%BB%83%22%5D%0A%20%20TRAIN%20--%3E%20EVAL%5B%22%E5%8E%9F%E7%94%9F%E5%8D%B7%E8%AF%84%E6%B5%8B%E5%8A%A0%E8%A6%86%E7%9B%96%E7%BC%BA%E5%8F%A3%E6%8A%A5%E5%91%8A%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>低资源工程受三个硬边界约束。第一，翻译腔会自我强化，合成数据的占比要设上限并用母语者抽检；第二，评测集本身是稀缺资源：把小测试集反复跑成「能力证明」，是把噪声当信号，覆盖声明要止于已测语言；<span class="marginnote">译文卷与原生卷的区别可以这么记：原生卷是母语者用这门语言直接出的题，译文卷是把英语题翻译过来的题。只考译文卷，等于只验证「模型会不会这门翻译腔」，初学者容易把两者混为一谈，误以为译文卷高分等于语言能力达标。</span>第三，伦理与社区：语言是身份，未经社区参与的数据采集与「濒危语言拯救」叙事容易变成单方面提取，MasakhaNER 一类共建模式的价值正在于此——数据与评测由该语言的研究者主导。低资源不是慈善项目尾注，它决定产品能诚实声明多大的覆盖范围。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>低资源按说话人与数据量之比分档；人多数据少的语言最难，不是地理意义上的小语种。</li><li>数据三路径：原生爬取、翻译合成、社区采集；配比进台账，翻译腔单独评估并设上限。</li><li>模型侧按档位降级：小模型小词表或字节路径；NLLB-200 是流水线标杆。</li><li>评测只有译文卷时必须声明缺口；不把小测试集的噪声当能力证明。</li><li>社区共建优于单方面提取；覆盖声明止于已测语言。</li><li>出处：Joshi et al., ACL 2020；Ogueji et al., AfriBERTa, 2021；Adelani et al., MasakhaNER, 2021；Team NLLB, 2022；Goyal et al., FLORES-101, TACL 2022。</li></ul>',4))])}const T=o(m,[["render",h]]);export{C as __pageData,T as default};
